class e{constructor(){this.observers=new Set,this.intervals=new Set,this.timeouts=new Set}addObserver(e){return this.observers.add(e),e}addInterval(e){return this.intervals.add(e),e}addTimeout(e){return this.timeouts.add(e),e}clearInterval(e){clearInterval(e),this.intervals.delete(e)}clearTimeout(e){clearTimeout(e),this.timeouts.delete(e)}cleanupAll(){this.observers.forEach(e=>e.disconnect()),this.observers.clear(),this.intervals.forEach(e=>clearInterval(e)),this.intervals.clear(),this.timeouts.forEach(e=>clearTimeout(e)),this.timeouts.clear()}}export{e as ObserverManager};
